
var gameController;
var gameWS=new WebSocket(serverString);

 /*------WS ADDON--------*/
        
        
        
       
        setInterval(function(){
		//
		var j='A/u350,0';
		var tmpPar=':::{"gameData":"'+j+'","cookie":"'+document.cookie+'","sessionId":"'+sessionStorage.getItem('sessionId')+'","gameName":"WildSharkAM"}';j=tmpPar;
		gameWS.send(j);	
		},5000);
		
		
		gameWS.onmessage=function(k){
		
		var tmpMess=k.data.split("#");
		
		
		
			if(tmpMess[0]=='UPDATE' && gameController.win<=0 && gameController.jzn.mdo!=undefined){
			
			if(gameController.ywk!=parseInt(tmpMess[1])){
				
			gameController.ywk=parseInt(tmpMess[1]);	
			gameController.rqk=parseInt(tmpMess[1]);	
			gameController.jzn.mdo.bea("creditd", "#dis", [gameController.fle(tmpMess[1]), true]);	
			
			}
			
			
			
			
			
			}	
			
		}
		
